function reverseCaseMatch(s) {
  let l = 0,
    r = s.length - 1;
  while (l < s.length && r >= 0) {
    if (!/[a-z]/.test(s[l])) {
      l++;
    } else if (!/[A-Z]/.test(s[r])) {
      r--;
    } else {
      if (s[l] !== s[r].toLowerCase()) {
        return false;
      }
      l++;
      r--;
    }
  }
  return true;
}

